#include <bits/stdc++.h>
#define MAXN 5000010
#define INF_VAL 1000000000
#define IDX(x,k) (x+(k-1)*n)
using namespace std;
template<typename T> void get_input(T &x)
{
    x=0; char c=getchar(); bool neg=false;
    while(!isdigit(c)){if(c=='-') neg=true;c=getchar();}
    while(isdigit(c)){x=(x<<1)+(x<<3)+(c^48); c=getchar();}
    if(neg) x=-x;
}
int n,m,k,v1,v2,s,t;
int dist_arr[MAXN];
bool vis_arr[MAXN];
struct EdgeStruct
{
    int to,next,v,cost;
} edges[MAXN];
int head_arr[MAXN],edge_idx=1;
void add_edge(int from,int to,int val,int cost)
{
    edges[++edge_idx]=(EdgeStruct){to,head_arr[from],val,cost}; head_arr[from]=edge_idx;
    edges[++edge_idx]=(EdgeStruct){from,head_arr[to],0,-cost}; head_arr[to]=edge_idx;
}
bool find_shortest_path()
{
    queue<int> q;
    for(int i=s;i<=t;++i) dist_arr[i]=INF_VAL,vis_arr[i]=false;
    q.push(s); dist_arr[s]=0; vis_arr[s]=true;
    while(!q.empty())
    {
        int x=q.front(); q.pop(); vis_arr[x]=false;
        for(int i=head_arr[x];i;i=edges[i].next)
        {
            int y=edges[i].to,c=edges[i].cost;
            if(dist_arr[y]<=dist_arr[x]+c||!edges[i].v) continue;
            dist_arr[y]=dist_arr[x]+c;
            if(!vis_arr[y]) {vis_arr[y]=true; q.push(y);}
        }
    }
    return dist_arr[t]!=INF_VAL;
}
int augment_flow(int x,int limit)
{
    if(x==t) return limit;
    vis_arr[x]=true;
    int res=limit;
    for(int i=head_arr[x];i;i=edges[i].next)
    {
        int y=edges[i].to,v=edges[i].v;
        if(dist_arr[y]!=dist_arr[x]+edges[i].cost||!v||vis_arr[y]) continue;
        if(int f=augment_flow(y,min(res,v)))
        {
            res-=f;
            edges[i].v-=f;
            edges[i^1].v+=f;
            if(!res) break;
        }
    }
    return limit-res;
}
int compute_min_cost()
{
    int total=0, flow;
    while(find_shortest_path())
        while(flow=augment_flow(s,INF_VAL))
            total+=flow*dist_arr[t];
    return total;
}
int main()
{
    get_input(n); get_input(m); get_input(k); get_input(v1); get_input(v2);
    t=IDX(n,110)+1;
    for(int i=2;i<=110;++i) add_edge(IDX(1,i),t,INF_VAL,0);
    for(int i=2;i<=n;++i)
        for(int j=1;j<110;++j)
            add_edge(IDX(i,j),IDX(i,j+1),INF_VAL,v1);
    for(int i=1,x;i<=k;++i) {get_input(x); add_edge(s,IDX(x,1),1,0);}
    for(int i=1;i<=m;++i)
    {
        int x,y;
        get_input(x); get_input(y);
        for(int j=1;j<110;++j)
            for(int l=1;l<=k;++l)
                add_edge(IDX(x,j),IDX(y,j+1),1,v2*(2*l-1)+v1),
                add_edge(IDX(y,j),IDX(x,j+1),1,v2*(2*l-1)+v1);
    }
    printf("%d",compute_min_cost());
    return 0;
}
